import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, of, delay, map } from 'rxjs';
import { Calendar, DateRange } from '../models/calendar.model';
import { CalendarEvent, RecurrenceRule, EventResponseStatus } from '../models/event.model';
import { MOCK_CALENDARS, MOCK_EVENTS } from '../mock/mock-calendar-data';
import { isWithinInterval, areIntervalsOverlapping, startOfDay, endOfDay, addDays, addWeeks, addMonths, addYears, differenceInMilliseconds } from 'date-fns';

@Injectable({ providedIn: 'root' })
export class CalendarService {
  private calendarsSubject = new BehaviorSubject<Calendar[]>([...MOCK_CALENDARS]);
  private eventsSubject = new BehaviorSubject<CalendarEvent[]>([...MOCK_EVENTS]);

  readonly calendars$ = this.calendarsSubject.asObservable();
  readonly rawEvents$ = this.eventsSubject.asObservable();
  readonly events$ = this.rawEvents$.pipe(
    map(events => CalendarService.expandRecurringEventsStatic(events))
  );

  private nextEventId = 100;

  listCalendars(): Observable<Calendar[]> {
    return this.calendars$;
  }

  listEvents(range?: DateRange, calendarIds?: string[]): Observable<CalendarEvent[]> {
    return this.events$.pipe(
      map(events => {
        // 繰り返しイベントを展開
        let expanded = CalendarService.expandRecurringEventsStatic(events, range);

        if (calendarIds && calendarIds.length > 0) {
          expanded = expanded.filter(e => calendarIds.includes(e.calendarId));
        }
        if (range) {
          expanded = expanded.filter(e => {
            return areIntervalsOverlapping(
              { start: e.start, end: e.end },
              { start: range.start, end: range.end }
            );
          });
        }
        return expanded;
      })
    );
  }

  /** 繰り返しルールに基づいてイベントを展開する */
  static expandRecurringEventsStatic(events: CalendarEvent[], range?: DateRange): CalendarEvent[] {
    const result: CalendarEvent[] = [];
    const rangeStart = range?.start || addMonths(new Date(), -1);
    const rangeEnd = range?.end || addMonths(new Date(), 2);

    for (const event of events) {
      if (!event.recurrence) {
        result.push(event);
        continue;
      }

      // 元のイベントも含める
      result.push(event);

      const duration = differenceInMilliseconds(event.end, event.start);
      const rec = event.recurrence;
      const maxOccurrences = rec.count || 52; // 最大52回
      const isWeekdays = rec.byDay?.length === 5;

      let current = new Date(event.start);
      for (let i = 1; i < maxOccurrences; i++) {
        // 次の日付を計算
        switch (rec.frequency) {
          case 'daily':
            current = addDays(current, rec.interval);
            // 平日のみの場合、土日をスキップ
            if (isWeekdays) {
              while (current.getDay() === 0 || current.getDay() === 6) {
                current = addDays(current, 1);
              }
            }
            break;
          case 'weekly':
            current = addWeeks(current, rec.interval);
            break;
          case 'monthly':
            current = addMonths(current, rec.interval);
            break;
          case 'yearly':
            current = addYears(current, rec.interval);
            break;
        }

        // 範囲チェック
        if (rec.until && current > rec.until) break;
        if (current > rangeEnd) break;

        const instanceStart = new Date(current);
        const instanceEnd = new Date(instanceStart.getTime() + duration);

        if (instanceEnd < rangeStart) continue;

        result.push({
          ...event,
          id: `${event.id}-rec-${i}`,
          start: instanceStart,
          end: instanceEnd,
        });
      }
    }

    return result;
  }

  getEvent(id: string): Observable<CalendarEvent | undefined> {
    return this.events$.pipe(
      map(events => events.find(e => e.id === id))
    );
  }

  createEvent(event: Partial<CalendarEvent>): Observable<CalendarEvent> {
    const newEvent: CalendarEvent = {
      id: `evt-new-${this.nextEventId++}`,
      calendarId: event.calendarId || 'cal-personal',
      title: event.title || '(タイトルなし)',
      description: event.description,
      location: event.location,
      start: event.start || new Date(),
      end: event.end || new Date(),
      allDay: event.allDay || false,
      color: event.color,
      guests: event.guests || [],
      reminders: event.reminders || [{ method: 'popup', minutes: 15 }],
      recurrence: event.recurrence,
      attachments: event.attachments || [],
      videoConferenceUrl: event.videoConferenceUrl,
      visibility: event.visibility || 'busy',
      scheconLinked: event.scheconLinked,
      scheconEventId: event.scheconEventId,
      created: new Date(),
      updated: new Date(),
    };
    const current = this.eventsSubject.getValue();
    this.eventsSubject.next([...current, newEvent]);
    return of(newEvent).pipe(delay(200));
  }

  updateEvent(id: string, changes: Partial<CalendarEvent>): Observable<CalendarEvent> {
    const current = this.eventsSubject.getValue();
    const index = current.findIndex(e => e.id === id);
    if (index === -1) {
      throw new Error(`Event ${id} not found`);
    }
    const updated = { ...current[index], ...changes, updated: new Date() };
    const newList = [...current];
    newList[index] = updated;
    this.eventsSubject.next(newList);
    return of(updated).pipe(delay(200));
  }

  deleteEvent(id: string): Observable<boolean> {
    const current = this.eventsSubject.getValue();
    this.eventsSubject.next(current.filter(e => e.id !== id));
    return of(true).pipe(delay(200));
  }

  inviteGuests(eventId: string, guestEmails: string[]): Observable<CalendarEvent> {
    const current = this.eventsSubject.getValue();
    const evt = current.find(e => e.id === eventId);
    if (!evt) {
      throw new Error(`Event ${eventId} not found`);
    }
    const newGuests = guestEmails
      .filter(email => !evt.guests.some(g => g.email === email))
      .map(email => ({
        email,
        displayName: email.split('@')[0],
        responseStatus: 'needsAction' as EventResponseStatus,
      }));
    return this.updateEvent(eventId, {
      guests: [...evt.guests, ...newGuests],
    });
  }

  respondToEvent(eventId: string, response: EventResponseStatus): Observable<CalendarEvent> {
    return this.updateEvent(eventId, {});
  }

  toggleCalendarVisibility(calendarId: string): void {
    const current = this.calendarsSubject.getValue();
    const updated = current.map(c =>
      c.id === calendarId ? { ...c, visible: !c.visible } : c
    );
    this.calendarsSubject.next(updated);
  }

  getAvailability(
    date: Date,
    calendarIds?: string[]
  ): Observable<{ start: Date; end: Date; busy: boolean }[]> {
    return this.events$.pipe(
      map(events => {
        const dayStart = startOfDay(date);
        const dayEnd = endOfDay(date);
        const dayEvents = events.filter(e => {
          if (calendarIds && !calendarIds.includes(e.calendarId)) return false;
          if (e.allDay) return false;
          return areIntervalsOverlapping(
            { start: e.start, end: e.end },
            { start: dayStart, end: dayEnd }
          );
        });
        const slots: { start: Date; end: Date; busy: boolean }[] = [];
        for (let hour = 0; hour < 24; hour++) {
          const slotStart = new Date(date);
          slotStart.setHours(hour, 0, 0, 0);
          const slotEnd = new Date(date);
          slotEnd.setHours(hour + 1, 0, 0, 0);
          const busy = dayEvents.some(e =>
            areIntervalsOverlapping(
              { start: e.start, end: e.end },
              { start: slotStart, end: slotEnd }
            )
          );
          slots.push({ start: slotStart, end: slotEnd, busy });
        }
        return slots;
      })
    );
  }

  /** Search events by title, description, or location */
  searchEvents(term: string): Observable<CalendarEvent[]> {
    if (!term) return of([]);
    const lower = term.toLowerCase();
    return this.events$.pipe(
      map(events => events.filter(e =>
        e.title.toLowerCase().includes(lower) ||
        (e.description && e.description.toLowerCase().includes(lower)) ||
        (e.location && e.location.toLowerCase().includes(lower))
      ))
    );
  }

  /** Mock contact search for guest picker */
  searchContacts(query: string): Observable<{ email: string; displayName: string }[]> {
    const contacts = [
      { email: 'tanaka@example.com', displayName: '田中太郎' },
      { email: 'suzuki@example.com', displayName: '鈴木花子' },
      { email: 'yamada@example.com', displayName: '山田一郎' },
      { email: 'sato@example.com', displayName: '佐藤健太' },
      { email: 'designer@example.com', displayName: '高橋美咲' },
      { email: 'pm@example.com', displayName: '小林PM' },
      { email: 'hr-kato@example.com', displayName: '加藤（人事）' },
      { email: 'ceo@example.com', displayName: '代表 中村' },
    ];
    if (!query) return of([]);
    const lower = query.toLowerCase();
    return of(
      contacts.filter(
        c =>
          c.displayName.toLowerCase().includes(lower) ||
          c.email.toLowerCase().includes(lower)
      )
    ).pipe(delay(100));
  }
}
